from typing import List


class Solution:
    def countSubarrays(self, nums: List[int]) -> int:
        seen = set()
        count = 0
        for i in range(len(nums) - 2):
            if 2 * (nums[i] + nums[i + 2]) == nums[i + 1] and tuple(nums[i:i + 3]) not in seen:
                seen.add(tuple(nums[i:i + 3]))
                count += 1
        return count

from typing import List


class Solution:
    def countSubarrays(self, nums: List[int]) -> int:
        count = 0
        for i in range(len(nums) - 2):
            if nums[i + 1] >= 0 and 2 * (nums[i] + nums[i + 2]) == nums[i + 1]:
                count += 1
        return count

from typing import List


class Solution:
    def countSubarrays(self, nums: List[int]) -> int:
        count = 0
        i = 0
        while i < len(nums) - 2:
            if 2 * (nums[i] + nums[i + 2]) == nums[i + 1]:
                count += 1
                i += 2
            i += 1
        return count
